<body>
<div class="container">
<h1>Todo App</h1>
<input type="text" id="input" placeholder="Add a new todo..." autocomplete="off">
<button class="add-btn" id="addBtn">Add</button>
<div class="filter">
<button id="all" class="active">All</button>
<button id="active">Active</button>
<button id="completed">Completed</button>
</div>
<div id="list"></div>
</div>
<script>
const input=document.getElementById('input'),addBtn=document.getElementById('addBtn'),list=document.getElementById('list');
const allBtn=document.getElementById('all'),activeBtn=document.getElementById('active'),completedBtn=document.getElementById('completed');
let todos=[],filter='all',nextId=1;

function load() { try{todos=JSON.parse(localStorage.getItem('todos'))||[];nextId=Number(localStorage.getItem('nextId'))||1}catch(e){} }
function save() { localStorage.setItem('todos',JSON.stringify(todos));localStorage.setItem('nextId',nextId.toString()); }
function render() {
  list.innerHTML='';
  const filtered=todos.filter(t=>{
    if(filter==='all')return true;
    if(filter==='active')return !t.done;
    return t.done;
  });
  if(filtered.length===0){list.innerHTML='<div class="empty">No todos here</div>';return;}
  filtered.forEach(t=>{
    const el=document.createElement('div');
    el.className='todo-item'+(t.done?' completed':'');
    el.innerHTML='<input class="todo-checkbox" type="checkbox" checked="'+t.done+'" data-id="'+t.id+'"><span class="todo-text">'+t.text+'</span><button class="delete-btn" data-id="'+t.id+'">&times;</button>';
    el.querySelector('input').addEventListener('change',e=>{const id=e.target.dataset.id;const idx=todos.findIndex(x=>x.id===id);if(idx!==-1){todos[idx].done=e.target.checked;save();render();}});
    el.querySelector('.delete-btn').addEventListener('click',e=>{e.stopPropagation();todos=todos.filter(x=>x.id!==e.target.dataset.id);save();render();});
    list.appendChild(el);
  });
}
function add() {
  const text=input.value.trim();
  if(!text)return;
  todos.push({id:nextId++,text,done:false});
  save();render();
  input.value='';
}
function toggleFilter(f){
  filter=f;
  [allBtn,activeBtn,completedBtn].forEach(b=>b.classList.toggle('active',b.id===f==='all'?f==='all':f==='active'?b.id==='active':f==='completed'));
  render();
}
addBtn.addEventListener('click',add);
input.addEventListener('keydown',e=>{if(e.key==='Enter')add()});
allBtn.addEventListener('click',()=>toggleFilter('all'));
activeBtn.addEventListener('click',()=>toggleFilter('active'));
completedBtn.addEventListener('click',()=>toggleFilter('completed'));
load();
render();
</script>
</body>
